def solve(I):
    H,W=len(I),len(I[0])
    pts=[(i,j) for i in range(H) for j in range(W) if I[i][j]==2]
    O=[r[:] for r in I]
    from collections import Counter
    cnt=Counter(i for i,j in pts)
    row=max(cnt,key=lambda r:cnt[r])   # anchor row
    cands=[j for i,j in pts if i==row]
    lo,hi=min(cands),max(cands)
    for c in range(lo,hi+1):
        if O[row][c]==0: O[row][c]=3
    for i,j in pts:
        if i!=row:
            rng=range(min(i,row),max(i,row)+1)
            for k in rng:
                if O[k][j]==0: O[k][j]=3
    return O
print(solve(G['Demo pair 1 input'])==G['Demo pair 1 output'])
